#!/usr/bin/env python3
"""Print a CSV file as a padded table."""
import csv
import sys

FMT = "%-8s  %-3s  %-6s"


def main(path):
    with open(path, newline="") as f:
        rows = list(csv.reader(f))
    for row in rows:
        print((FMT % (row[0], row[1], row[2])).rstrip())


if __name__ == "__main__":
    main(sys.argv[1])
